S.DuoWaitStartedAt, S.DuoWaitReleased, S.DuoWaitName = nil, false, nil
S.PhaseStart = Now
S.WalkStart = Now
S.WaitUntil = nil
S.FightStart = nil
S.SeenTarget = false
S.FoughtThisVisit = false
S.LastTarget = nil
S.TargetSeenAt = nil
ClearKillClock()
S.Teleported = false
S.PathIndex = 1
S.Path = Stop.Path and table.clone(Stop.Path) or {}
S.InteractAt = nil
S.TeleportFrom = nil
S.TeleportAt = nil
S.Teleports = 0
S.TeleportLanded = false
S.TeleportHold = nil
S.PromptUsed = false
S.PromptCheckAt = nil
S.PromptTargetPosition = nil
S.FloorLifts = 0
S.SpotWaitUntil = nil
SetBlocking(false)
S.SkipSpotWait = S.SkipSpotWaitNext == true
S.SkipSpotWaitNext = false
S.InteractSuppressed = false
S.PromptFallback = nil
S.ResetHumanoid = nil
S.ResetFiredAt = nil
S.ResetRetries = 0
S.RestartStop = false
S.ReturnKill = false
S.ReturnMissAt = nil
S.RecoveredAt = nil
StopFlee()
S.HpAt = nil
S.HpBase = nil
S.SkillWas = false
EndDodge()
S.BestDistance = nil
