Default = BOX_STYLE_NAMES[S.Settings.BoxStyle],
Callback = function(Value)
S.Settings.BoxStyle = BOX_STYLE_KEYS[Value] or "Full"
SaveSetting("ESP_BOX_STYLE", S.Settings.BoxStyle)
Clear()
