}
for _, Kind in ipairs(KINDS) do
local C = S.Kinds[Kind]
local Sec = UIRef.EspTab:AddSection{ Title = TITLES[Kind], Side = "Right" }
Controls.Kinds[Kind] = Sec:AddToggle{
Name = Kind .. " ESP",
