if Value then
SetStyle(Kind, "Box")
else
C.Box = false
SaveStyle(Kind)
Rebuild(Kind)
end
end,
}
S.StyleToggles[Kind] = { Outline = OutlineToggle, Box = BoxToggle }
Controls.Text[Kind] = Sec:AddToggle{
Name = Kind .. " info text",
Default = C.Label,
Callback = function(Value)
